def ajustar_ohlc(df: pd.DataFrame) -> pd.DataFrame:
    """Ajusta OHLC con el factor adj_close/close, igual que EXP-005."""
    out = df.copy()
    cols = ["open", "high", "low", "close"]

    close = out["close"] if "close" in out.columns else pd.Series(np.nan, index=out.index)
    mask = close.isna() | (close == 0)

    if "adj_close" in out.columns:
        factor = out["adj_close"] / close
        for col in cols:
            if col in out.columns:
                out[col] = out[col] * factor

    for col in cols:
        if col in out.columns:
            out.loc[mask, col] = np.nan

    return out


