from __future__ import annotations

import json
import math
from pathlib import Path
from typing import Any, Iterable

import numpy as np
import pandas as pd

from prl.short_pressure import baselines, evaluation, features, grid


# ---------------------------------------------------------------------------
# Constantes internas
# ---------------------------------------------------------------------------

SHORT_COLS = [
    "short_volume_ratio",
    "short_volume_ratio_zscore_20d",
    "days_to_cover",
    "short_interest_change_pct",
]

PRICE_COLS = [
    "ret_1d",
    "ret_5d",
    "ret_20d",
    "drawdown_5d",
    "drawdown_20d",
    "drawdown_60d",
    "dist_sma20",
    "dist_sma50",
    "dist_sma200",
    "rsi_2",
    "rsi_14",
    "realized_vol_20d",
    "rel_volume",
    "zscore_ret_5d",
]

NUM_COLS = SHORT_COLS + PRICE_COLS

CONF_COLS = [
    "confirmacion_a",
    "confirmacion_b",
    "confirmacion_c",
    "confirmacion_d",
    "confirmacion_e",
]

FINRA_FFILL_COLS = {
    "short_volume_ratio",
    "days_to_cover",
    "short_interest_change_pct",
}

BASELINE_KEYS = [
    "baseline_buy_hold",
    "baseline_caida_simple",
    "baseline_price_exhaustion",
    "baseline_short_pressure",
    "baseline_combo_ingenuo",
]

STRATEGY_KEYS = ["ganador"] + BASELINE_KEYS


# ---------------------------------------------------------------------------
# Utilidades
# ---------------------------------------------------------------------------


def _leer_universo(path: Path) -> list[str]:
    lineas = Path(path).read_text(encoding="utf-8").splitlines()
    return [ln.strip() for ln in lineas if ln.strip()]


def ajustar_ohlc(df: pd.DataFrame) -> pd.DataFrame:
    """Ajusta OHLC por el factor adj_close / close.

    Es idéntica a la función homónima del EXP-005: multiplica open/high/low/close
    por ``adj_close / close`` y fuerza NaN donde ``close`` es 0 o NaN.
    """
    out = df.copy()
    if "adj_close" not in out.columns:
        return out

    close = pd.to_numeric(out["close"], errors="coerce")
    adj_close = pd.to_numeric(out["adj_close"], errors="coerce")
    factor = adj_close / close
    factor = factor.where(close.notna() & (close != 0), np.nan)

    for col in ("open", "high", "low", "close"):
        if col in out.columns:
            out[col] = pd.to_numeric(out[col], errors="coerce") * factor

    return out


def retorno_forward(precio_cierre: pd.Series, dias: int) -> pd.Series:
    return precio_cierre.shift(-int(dias)) / precio_cierre - 1.0


def _empty_short_volume() -> pd.DataFrame:
    return pd.DataFrame(columns=["date", "short_volume_ratio"])


def _empty_short_interest() -> pd.DataFrame:
    return pd.DataFrame(
        columns=[
            "settlement_date",
            "days_to_cover",
            "short_interest_change_pct",
        ]
    )


def _read_finra_groups(path: Path | str) -> dict[str, pd.DataFrame]:
    df = pd.read_parquet(path)
    if df.empty or "symbol" not in df.columns:
        return {}

    for col in ("date", "settlement_date"):
        if col in df.columns:
            df[col] = pd.to_datetime(df[col])

    return {
        str(sym): grp.copy()
        for sym, grp in df.groupby("symbol", sort=False)
    }


def _normalizar_mask(mask: Any, index: pd.Index) -> pd.Series:
    if isinstance(mask, pd.Series):
        m = mask.reindex(index)
    else:
        m = pd.Series(mask, index=index)
    return m.fillna(False).astype(bool)


def _to_float_or_none(value: Any) -> float | None:
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    try:
        out = float(value)
    except (TypeError, ValueError):
        return None
    if math.isnan(out) or math.isinf(out):
        return None
    return out


def _jsonable(obj: Any) -> Any:
    if isinstance(obj, dict):
        return {str(k): _jsonable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_jsonable(v) for v in obj]
    if isinstance(obj, np.ndarray):
        return [_jsonable(v) for v in obj.tolist()]
    if isinstance(obj, (pd.Timestamp,)):
        return obj.isoformat()
    if obj is pd.NaT or obj is pd.NA:
        return None
    if isinstance(obj, (np.bool_, bool)):
        return bool(obj)
    if isinstance(obj, np.integer):
        return int(obj)
    if isinstance(obj, (np.floating, float)):
        out = float(obj)
        if math.isnan(out) or math.isinf(out):
            return None
        return out
    if isinstance(obj, int):
        return int(obj)
    if isinstance(obj, str) or obj is None:
        return obj
    return obj


def _variant_id(variant: dict) -> str:
    sp = int(round(float(variant["umbral_short_pressure"]) * 100))
    pe = int(round(float(variant["umbral_price_exhaustion"]) * 100))
    conf = variant.get("confirmaciones", ())
    conf_txt = "".join(conf) if conf else "ninguna"
    return f"sp{sp}_pe{pe}_conf{conf_txt}"


