    fecha: pd.Timestamp,
    simbolos: list[str],
    precios: dict[str, pd.DataFrame],
    feats: dict[str, pd.DataFrame],
    fwd: dict[str, dict[int, pd.Series]],
    horizontes: tuple[int, ...],
