) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Construye ``features_crudas`` y la tabla percentil para una fecha."""
    rows: dict[str, dict[str, Any]] = {}

    for sym in simbolos:
        if sym not in precios or sym not in feats:
            continue

        df_precio = precios[sym]
        if int((df_precio.index <= fecha).sum()) < int(min_historia):
            continue

        f = feats[sym]
        if fecha not in f.index:
            continue

        row = f.loc[fecha]
        if isinstance(row, pd.DataFrame):
            row = row.iloc[-1]

        valores: dict[str, Any] = {}
        ok = True

        for col in SHORT_COLS:
            if col in FINRA_FFILL_COLS:
                serie = f[col].loc[:fecha]
                if serie.empty:
                    ok = False
                    break
                val = serie.ffill().iloc[-1]
            else:
                val = row.get(col, np.nan)

            if pd.isna(val):
                ok = False
                break
            valores[col] = float(val)

        if not ok:
            continue

        for col in PRICE_COLS:
            val = row.get(col, np.nan)
            if pd.isna(val):
                ok = False
                break
            valores[col] = float(val)

        if not ok:
            continue

        for col in CONF_COLS:
            val = row.get(col, pd.NA)
            if pd.isna(val):
                ok = False
                break
            valores[col] = bool(val)

        if not ok:
            continue

        for h in horizontes:
            col_ret = f"retorno_{int(h)}d"
            if h in fwd.get(sym, {}):
                serie_fwd = fwd[sym][h]
                if fecha in serie_fwd.index:
                    valores[col_ret] = serie_fwd.at[fecha]
                else:
                    valores[col_ret] = np.nan
            else:
                valores[col_ret] = np.nan

        rows[sym] = valores

    all_cols = NUM_COLS + CONF_COLS + [
        f"retorno_{int(h)}d" for h in horizontes
    ]

    if rows:
        crudas = pd.DataFrame.from_dict(rows, orient="index")
    else:
        crudas = pd.DataFrame(columns=all_cols)

    for col in all_cols:
        if col not in crudas.columns:
            crudas[col] = np.nan
    crudas = crudas[all_cols]

    if crudas.empty:
        pct = pd.DataFrame(columns=all_cols + [
            "SHORT_PRESSURE_SCORE",
            "PRICE_EXHAUSTION_SCORE",
        ])
        return crudas, pct

    pct = crudas[NUM_COLS].rank(pct=True)

    pct_sp = pct[NUM_COLS].copy()
    sp_score = features.SHORT_PRESSURE_SCORE(pct_sp)
    pe_score = features.PRICE_EXHAUSTION_SCORE(pct_sp)

    pct["SHORT_PRESSURE_SCORE"] = sp_score
    pct["PRICE_EXHAUSTION_SCORE"] = pe_score

    for col in CONF_COLS:
        pct[col] = crudas[col]

    for h in horizontes:
        col = f"retorno_{int(h)}d"
        pct[col] = crudas[col]

    return crudas, pct


def _senales_variante(
    variant: dict,
    fechas: Iterable[pd.Timestamp],
    tablas_pct: dict[pd.Timestamp, pd.DataFrame],
    horizontes: tuple[int, ...],
    horizonte_principal: int,
) -> pd.DataFrame:
    registros: list[dict[str, Any]] = []
    col_principal = f"retorno_{int(horizonte_principal)}d"
    variant_id = variant.get("variant_id") or _variant_id(variant)

    for fecha in fechas:
        tabla = tablas_pct.get(fecha)
        if tabla is None or tabla.empty:
            continue

        try:
            mask = grid.aplicar_bucket(variant, tabla)
        except Exception:
            continue

        mask = _normalizar_mask(mask, tabla.index)
        if not bool(mask.any()):
            continue

        for sym in tabla.index[mask.to_numpy()]:
            if col_principal not in tabla.columns:
                continue
            ret_principal = tabla.at[sym, col_principal]
            if pd.isna(ret_principal):
                continue

            rec: dict[str, Any] = {
                "fecha": fecha,
                "symbol": str(sym),
                "simbolo": str(sym),
                "ticker": str(sym),
                "variant_id": variant_id,
            }
            for h in horizontes:
                col = f"retorno_{int(h)}d"
                rec[col] = tabla.at[sym, col] if col in tabla.columns else np.nan
            registros.append(rec)

    if registros:
        return pd.DataFrame(registros)

    cols = [
        "fecha",
        "symbol",
        "simbolo",
        "ticker",
        "variant_id",
    ] + [f"retorno_{int(h)}d" for h in horizontes]
    return pd.DataFrame(columns=cols)


def _serie_por_fecha(senales: pd.DataFrame, horizonte: int) -> pd.Series:
    if senales is None or senales.empty:
        return pd.Series(dtype=float)

    col = f"retorno_{int(horizonte)}d"
    if col not in senales.columns:
        return pd.Series(dtype=float)

    tmp = senales[["fecha", col]].dropna(subset=[col])
    if tmp.empty:
        return pd.Series(dtype=float)

    return (
        tmp.groupby("fecha")[col]
        .mean()
        .sort_index()
        .astype(float)
    )


def _metricas_horizonte(
    registros: list[dict[str, Any]],
    horizonte: int,
) -> dict[str, float | None]:
    col = f"retorno_{int(horizonte)}d"
    vals: list[float] = []

    for rec in registros:
        if col not in rec:
            continue
        val = rec[col]
        if pd.isna(val):
            continue
        vals.append(float(val))

    if not vals:
        return {
            "media": None,
            "mediana": None,
            "frac_positivo": None,
        }

    arr = np.asarray(vals, dtype=float)
    return {
        "media": float(np.mean(arr)),
        "mediana": float(np.median(arr)),
        "frac_positivo": float(np.mean(arr > 0.0)),
    }


def _concentracion_manual(senales: pd.DataFrame) -> dict[str, Any]:
    if senales is None or senales.empty:
        return {
            "n_senales": 0,
            "frac_max_ticker": 0.0,
            "ticker_max": None,
        }

    if "ticker" in senales.columns:
        col = "ticker"
    elif "symbol" in senales.columns:
        col = "symbol"
    elif "simbolo" in senales.columns:
        col = "simbolo"
    else:
        return {
            "n_senales": int(len(senales)),
            "frac_max_ticker": 0.0,
            "ticker_max": None,
        }

    counts = senales[col].astype(str).value_counts(dropna=False)
    if counts.empty:
        frac = 0.0
        ticker_max = None
    else:
        frac = float(counts.iloc[0] / counts.sum())
        ticker_max = str(counts.index[0])

    return {
        "n_senales": int(len(senales)),
        "frac_max_ticker": frac,
        "ticker_max": ticker_max,
    }


def _vecinos(valor: float, valores: list[float]) -> list[float]:
    vals = list(valores)
    if not vals:
        return []
    if valor in vals:
        idx = vals.index(valor)
    else:
        idx = int(np.argmin([abs(v - valor) for v in vals]))
    out: list[float] = []
    if idx > 0:
        out.append(float(vals[idx - 1]))
    if idx + 1 < len(vals):
        out.append(float(vals[idx + 1]))
    return out


# ---------------------------------------------------------------------------
# Orquestador
# ---------------------------------------------------------------------------


def run(
    inputs_dir: Path | str,
    short_volume_path: Path | str,
