    horizontes = tuple(dict.fromkeys(int(h) for h in horizontes))
    horizonte_principal = int(horizonte_principal)
    if horizonte_principal not in horizontes:
        horizontes = horizontes + (horizonte_principal,)

    max_h = max(horizontes) if horizontes else 0
    if paso_dias <= 0:
        paso_dias = 1

    notes: list[str] = []

    # ------------------------------------------------------------------
    # 1. Universo y precios
    # ------------------------------------------------------------------
    universo = _leer_universo(universo_path)
    precios: dict[str, pd.DataFrame] = {}

    for sym in universo:
        path = inputs_dir / f"{sym}.parquet"
        if not path.exists():
            notes.append(f"{sym}: sin archivo de datos, omitido")
            continue

        raw = pd.read_parquet(path)
        if not isinstance(raw.index, pd.DatetimeIndex):
            if "date" in raw.columns:
                raw = raw.set_index("date")
            raw.index = pd.to_datetime(raw.index)

        raw = raw.sort_index()
        precios[sym] = ajustar_ohlc(raw)

    simbolos_con_datos = [s for s in universo if s in precios]

    if precios:
        fechas_union = sorted(set().union(*(set(df.index) for df in precios.values())))
        calendario = pd.DatetimeIndex(fechas_union)
    else:
        calendario = pd.DatetimeIndex([])

    # ------------------------------------------------------------------
    # 2. Datos FINRA consolidados
    # ------------------------------------------------------------------
    short_volume_groups = _read_finra_groups(short_volume_path)
    short_interest_groups = _read_finra_groups(short_interest_path)

    # ------------------------------------------------------------------
    # 3. Features por símbolo, historia completa
    # ------------------------------------------------------------------
    feats: dict[str, pd.DataFrame] = {}
