    for sym, df in precios.items():
        sv = short_volume_groups.get(sym, _empty_short_volume())
        si = short_interest_groups.get(sym, _empty_short_interest())

        df_ohlcv = df[
            [c for c in ("open", "high", "low", "close", "volume") if c in df.columns]
        ].copy()

        f = features.calcular_features_simbolo(df_ohlcv, sv, si)
        feats[sym] = f

        fwd[sym] = {}
        for h in horizontes:
            fwd[sym][h] = retorno_forward(df["close"], int(h))

    # ------------------------------------------------------------------
    # 4. Fechas de corte
    # ------------------------------------------------------------------
    discovery_start_ts = pd.Timestamp(discovery_start)
    discovery_end_ts = pd.Timestamp(discovery_end)
    validation_end_ts = pd.Timestamp(validation_end)
    locked_end_ts = pd.Timestamp(locked_end)

    fechas_corte: list[pd.Timestamp] = []
    if len(calendario) > 0:
        pos_inicio = int(calendario.searchsorted(discovery_start_ts, side="left"))
        for pos in range(pos_inicio, len(calendario), paso_dias):
            fecha = pd.Timestamp(calendario[pos])
            if fecha > locked_end_ts:
                continue
            if max_h > 0 and (pos + max_h) >= len(calendario):
                continue
            fechas_corte.append(fecha)

    discovery = [f for f in fechas_corte if f < discovery_end_ts]
    validation = [
        f for f in fechas_corte
        if discovery_end_ts <= f <= validation_end_ts
    ]
    locked = [
        f for f in fechas_corte
        if validation_end_ts < f <= locked_end_ts
    ]

    fechas_t0 = {
        "discovery": len(discovery),
        "validation": len(validation),
        "locked": len(locked),
        "total": len(fechas_corte),
    }

    variantes = grid.build_grid()
    n_variantes_total = len(variantes)

    resultado_base: dict[str, Any] = {
        "experiment": "EXP-004",
        "n_simbolos_universo": len(universo),
        "n_simbolos_con_datos": len(simbolos_con_datos),
