"""EXP-004 — orquestador de short pressure.

Reimplementa solo la orquestación; las fórmulas viven en
`prl.short_pressure.{features, grid, baselines, evaluation}`.
"""

from __future__ import annotations

import json
import math
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd

from prl.short_pressure import baselines, evaluation, features, grid


# --------------------------------------------------------------------------- #
# Utilidades puras (idénticas a EXP-005)
# --------------------------------------------------------------------------- #

def ajustar_ohlc(df: pd.DataFrame) -> pd.DataFrame:
    """Ajusta OHLC por el factor ``adj_close / close`` (NaN donde close <= 0)."""
    out = df.copy()
    close = df["close"].astype(float)
    adj = df["adj_close"].astype(float)
    factor = adj / close.replace(0, np.nan)
    factor = factor.where(close.notna() & (close != 0))
    for col in ("open", "high", "low", "close"):
        out[col] = df[col].astype(float) * factor
    return out


def retorno_forward(precio_cierre: pd.Series, dias: int) -> pd.Series:
    """Retorno forward de ``dias`` sesiones."""
    return precio_cierre.shift(-dias) / precio_cierre - 1


# --------------------------------------------------------------------------- #
# Columnas
# --------------------------------------------------------------------------- #

FINRA_FFILL = ["short_volume_ratio", "days_to_cover", "short_interest_change_pct"]

NUMERIC_COLS = [
    "short_volume_ratio",
    "short_volume_ratio_zscore_20d",
    "days_to_cover",
    "short_interest_change_pct",
    "ret_1d",
    "ret_5d",
    "ret_20d",
    "drawdown_5d",
    "drawdown_20d",
    "drawdown_60d",
    "dist_sma20",
    "dist_sma50",
    "dist_sma200",
    "rsi_2",
    "rsi_14",
    "realized_vol_20d",
    "rel_volume",
    "zscore_ret_5d",
]

CONF_COLS = [
    "confirmacion_a",
    "confirmacion_b",
    "confirmacion_c",
    "confirmacion_d",
    "confirmacion_e",
]

ALL_COLS = NUMERIC_COLS + CONF_COLS

BASELINES = [
    "baseline_buy_hold",
    "baseline_caida_simple",
    "baseline_price_exhaustion",
    "baseline_short_pressure",
    "baseline_combo_ingenuo",
]


# --------------------------------------------------------------------------- #
# Helpers internos
# --------------------------------------------------------------------------- #

def _nanmean(vals: list[Any]) -> float:
    arr = np.array(
        [float(v) for v in vals if v is not None and not (isinstance(v, float) and math.isnan(v))],
        dtype=float,
    )
    return float(np.mean(arr)) if arr.size else float("nan")


def _limpiar_bool(serie: Any, idx: pd.Index) -> pd.Series:
    s = pd.Series(serie)
    s = s.reindex(idx)
    s = s.where(s.notna(), False)
    try:
        s = s.astype(bool)
    except Exception:
        s = s.map(lambda x: bool(x) if not pd.isna(x) else False).astype(bool)
    return s


def _to_py(obj: Any) -> Any:
    if isinstance(obj, dict):
        return {str(k): _to_py(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_to_py(v) for v in obj]
    if isinstance(obj, np.ndarray):
        return [_to_py(v) for v in obj.tolist()]
    if isinstance(obj, (np.bool_,)):
        return bool(obj)
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (np.floating,)):
        f = float(obj)
        return None if (math.isnan(f) or math.isinf(f)) else f
    if isinstance(obj, float):
        return None if (math.isnan(obj) or math.isinf(obj)) else obj
    if obj is pd.NA or obj is pd.NaT:
        return None
    if isinstance(obj, pd.Timestamp):
        return obj.isoformat()
    if obj is None:
        return None
    if isinstance(obj, bool):
        return obj
    if isinstance(obj, int):
        return obj
    if isinstance(obj, str):
        return obj
    return obj


# --------------------------------------------------------------------------- #
# Orquestador
# --------------------------------------------------------------------------- #

def run(
    inputs_dir,
    short_volume_path,
    short_interest_path,
    universo_path,
    run_dir,
    discovery_start: str = "2019-02-01",
    discovery_end: str = "2022-12-31",
    validation_end: str = "2024-06-30",
    locked_end: str = "2026-11-01",
    paso_dias: int = 10,
    min_historia: int = 252,
    horizontes=(5, 10, 20),
    horizonte_principal: int = 10,
    min_senales_discovery: int = 30,
    max_frac_ticker: float = 0.20,
    n_particiones_pbo: int = 10,
    n_boot: int = 10000,
    n_placebos: int = 1000,
    seed: int = 0,
) -> dict:
    inputs_dir = Path(inputs_dir)
    run_dir = Path(run_dir)
    run_dir.mkdir(parents=True, exist_ok=True)

    horizontes = tuple(int(h) for h in horizontes)
    col_principal = f"retorno_{horizonte_principal}d"

    notes: list[str] = []
    notes.append(
        "MFE/MAE/drawdown post-señal/tiempo-a-objetivo fuera de alcance v1."
    )
    notes.append("Análisis por sector fuera de alcance (sin clasificación GICS).")
    notes.append(
        "Análisis por régimen bull/bear y volatilidad alta/baja declarado como "
        "exploratorio-no-incluido-en-v1."
    )
    notes.append(
        "baseline 5 (price exhaustion sin short pressure) idéntico al baseline 3 "
        "por diseño del pre-registro; se reporta una sola vez."
    )

    # 1. Universo y precios -------------------------------------------------- #
    universo = [ln.strip() for ln in Path(universo_path).read_text().splitlines() if ln.strip()]
    precios: dict[str, pd.DataFrame] = {}
    for t in universo:
        f = inputs_dir / f"{t}.parquet"
        if not f.exists():
            notes.append(f"{t}: sin archivo de datos, omitido")
            continue
        df = pd.read_parquet(f)
        if not isinstance(df.index, pd.DatetimeIndex):
            if "date" in df.columns:
                df = df.set_index("date")
        df = df.copy()
        df.index = pd.to_datetime(df.index)
        df = df.sort_index()
        df = ajustar_ohlc(df)
        precios[t] = df

    if precios:
        master = precios[next(iter(precios))].index
        for df in precios.values():
            master = master.union(df.index)
        master = master.sort_values()
    else:
        master = pd.DatetimeIndex([])

    # 2. Datos FINRA --------------------------------------------------------- #
    sv = pd.read_parquet(short_volume_path)
    si = pd.read_parquet(short_interest_path)
    sv_groups = {sym: g for sym, g in sv.groupby("symbol")}
    si_groups = {sym: g for sym, g in si.groupby("symbol")}

    # 3. Features por símbolo, historia completa ----------------------------- #
    data: dict[str, dict] = {}
    for t, df in precios.items():
        sv_t = sv_groups.get(t)
        if sv_t is None:
            sv_t = pd.DataFrame(
                {
                    "date": pd.to_datetime([]),
                    "short_volume_ratio": pd.Series(dtype=float),
                }
            )
        si_t = si_groups.get(t)
        if si_t is None:
            si_t = pd.DataFrame(
                {
                    "settlement_date": pd.to_datetime([]),
                    "days_to_cover": pd.Series(dtype=float),
                    "short_interest_change_pct": pd.Series(dtype=float),
                }
            )

        feat = features.calcular_features_simbolo(df, sv_t, si_t)
        feat = feat.copy()
        feat[FINRA_FFILL] = feat[FINRA_FFILL].ffill()

        fwds = {h: retorno_forward(df["close"], h) for h in horizontes}
        data[t] = {
            "feat": feat,
            "fwd": fwds,
            "price_index": df.index.sort_values(),
        }

    # 4. Fechas de corte ----------------------------------------------------- #
    max_h = max(horizontes) if horizontes else 0
    ts = pd.Timestamp
    corte: list[pd.Timestamp] = []
    if len(master) > 0:
        start = int(master.searchsorted(ts(discovery_start), side="left"))
        pos = start
        while pos < len(master):
            if pos + max_h >= len(master):
                break
            corte.append(master[pos])
            pos += paso_dias

    discovery = [d for d in corte if d < ts(discovery_end)]
    validation = [d for d in corte if ts(discovery_end) <= d <= ts(validation_end)]
    locked = [d for d in corte if ts(validation_end) < d <= ts(locked_end)]

    fechas_t0 = {
        "discovery": len(discovery),
        "validation": len(validation),
        "locked": len(locked),
    }

    # 5. Tablas cross-sectional por fecha ----------------------------------- #
    def build_table(fecha: pd.Timestamp) -> dict | None:
        crudas: dict[str, pd.Series] = {}
        rets: dict[str, dict[int, float]] = {}
        for t, d in data.items():
            fi = d["feat"]
            if fecha not in fi.index:
                continue
            pi = d["price_index"]
            n_le = int(pi.searchsorted(fecha, side="right"))
            if n_le < min_historia:
                continue
            row = fi.loc[fecha]
            if isinstance(row, pd.DataFrame):
                row = row.iloc[0]
            if row.isna().any():
                continue
            crudas[t] = row
            rr: dict[int, float] = {}
            for h in horizontes:
                serie_f = d["fwd"][h]
                rr[h] = float(serie_f.loc[fecha]) if fecha in serie_f.index else np.nan
            rets[t] = rr

        if not crudas:
            return None

        fdf = pd.DataFrame.from_dict(crudas, orient="index")
        fdf = fdf.reindex(columns=ALL_COLS)

        pct = fdf[NUMERIC_COLS].rank(pct=True)

        tabla = pd.DataFrame(index=fdf.index)
        tabla["SHORT_PRESSURE_SCORE"] = features.SHORT_PRESSURE_SCORE(pct)
        tabla["PRICE_EXHAUSTION_SCORE"] = features.PRICE_EXHAUSTION_SCORE(pct)
        for c in CONF_COLS:
            tabla[c] = fdf[c]

        ret_df = pd.DataFrame(
            {f"retorno_{h}d": pd.Series({t: rets[t][h] for t in crudas}) for h in horizontes}
        )
        return {"crudas": fdf, "tabla": tabla, "retornos": ret_df}

    all_fechas = sorted(set(discovery) | set(validation) | set(locked))
    tables: dict[pd.Timestamp, dict | None] = {f: build_table(f) for f in all_fechas}

    # 6. Grilla -------------------------------------------------------------- #
    variantes = grid.build_grid()
    n_grid = len(variantes)

    # 7. Filtro de soporte + selección -------------------------------------- #
    def senales_bucket(variant: dict, fechas: list[pd.Timestamp]) -> pd.DataFrame:
        rows = []
        for fecha in fechas:
            tb = tables.get(fecha)
            if tb is None:
                continue
            mask = grid.aplicar_bucket(variant, tb["tabla"])
            mask = _limpiar_bool(mask, tb["tabla"].index)
            idx = mask[mask].index
            rets = tb["retornos"]
            for s in idx:
                val = rets.at[s, col_principal] if s in rets.index else np.nan
                rows.append((fecha, s, float(val)))
        df = pd.DataFrame(rows, columns=["fecha", "symbol", col_principal])
        df["ticker"] = df["symbol"]
        df["simbolo"] = df["symbol"]
        return df

